#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Type {
    NamedType(NamedType),
    TypeVar(TypeVar),
    FunctionType(FunctionType),
    UnitType(UnitType),
    ParenType(ParenType),
    TupleType(TupleType),
    TupleConstructorType(TupleConstructorType),
    RecordType(RecordType),
}

impl AstNode for Type {
    fn can_cast(kind: SyntaxKind) -> bool {
        NamedType::can_cast(kind)
            || TypeVar::can_cast(kind)
            || FunctionType::can_cast(kind)
            || UnitType::can_cast(kind)
            || ParenType::can_cast(kind)
            || TupleType::can_cast(kind)
            || TupleConstructorType::can_cast(kind)
            || RecordType::can_cast(kind)
    }

    fn cast(syntax: SyntaxNode) -> Option<Self> {
        match syntax.kind() {
            SyntaxKind::NamedType => Some(Type::NamedType(NamedType { syntax })),
            SyntaxKind::TypeVar => Some(Type::TypeVar(TypeVar { syntax })),
            SyntaxKind::FunctionType => Some(Type::FunctionType(FunctionType { syntax })),
            SyntaxKind::UnitType => Some(Type::UnitType(UnitType { syntax })),
            SyntaxKind::ParenType => Some(Type::ParenType(ParenType { syntax })),
            SyntaxKind::TupleType => Some(Type::TupleType(TupleType { syntax })),
            SyntaxKind::TupleConstructorType => {
                Some(Type::TupleConstructorType(TupleConstructorType { syntax }))
            }
            SyntaxKind::RecordType => Some(Type::RecordType(RecordType { syntax })),
            _ => None,
        }
    }

    fn syntax(&self) -> &SyntaxNode {
        match self {
            Type::NamedType(it) => &it.syntax,
            Type::TypeVar(it) => &it.syntax,
            Type::FunctionType(it) => &it.syntax,
            Type::UnitType(it) => &it.syntax,
            Type::ParenType(it) => &it.syntax,
            Type::TupleType(it) => &it.syntax,
            Type::TupleConstructorType(it) => &it.syntax,
            Type::RecordType(it) => &it.syntax,
        }
    }
}

impl From<NamedType> for Type {
    fn from(node: NamedType) -> Type {
        Type::NamedType(node)
    }
}

impl From<TypeVar> for Type {
    fn from(node: TypeVar) -> Type {
        Type::TypeVar(node)
    }
}

impl From<FunctionType> for Type {
    fn from(node: FunctionType) -> Type {
        Type::FunctionType(node)
    }
}

impl From<UnitType> for Type {
    fn from(node: UnitType) -> Type {
        Type::UnitType(node)
    }
}

impl From<ParenType> for Type {
    fn from(node: ParenType) -> Type {
        Type::ParenType(node)
    }
}

impl From<TupleType> for Type {
    fn from(node: TupleType) -> Type {
        Type::TupleType(node)
    }
}

impl From<TupleConstructorType> for Type {
    fn from(node: TupleConstructorType) -> Type {
        Type::TupleConstructorType(node)
    }
}

impl From<RecordType> for Type {
    fn from(node: RecordType) -> Type {
        Type::RecordType(node)
    }
}

