#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum LetDecl {
    LetValue(LetValue),
    LetDestructure(LetDestructure),
}

impl AstNode for LetDecl {
    fn can_cast(kind: SyntaxKind) -> bool {
        LetValue::can_cast(kind) || LetDestructure::can_cast(kind)
    }

    fn cast(syntax: SyntaxNode) -> Option<Self> {
        match syntax.kind() {
            SyntaxKind::LetValue => Some(LetDecl::LetValue(LetValue { syntax })),
            SyntaxKind::LetDestructure => Some(LetDecl::LetDestructure(LetDestructure { syntax })),
            _ => None,
        }
    }

    fn syntax(&self) -> &SyntaxNode {
        match self {
            LetDecl::LetValue(it) => &it.syntax,
            LetDecl::LetDestructure(it) => &it.syntax,
        }
    }
}

impl From<LetValue> for LetDecl {
    fn from(node: LetValue) -> LetDecl {
        LetDecl::LetValue(node)
    }
}

impl From<LetDestructure> for LetDecl {
    fn from(node: LetDestructure) -> LetDecl {
        LetDecl::LetDestructure(node)
    }
}

